  app.put("/api/marketplace/listings/:id", isAuthenticated, async (req: any, res: any) => {
    try {
      const user = req.user as any;
      const { id } = req.params;

      // Check if user owns the listing
      const existingListing = await storage.getMarketplaceListing(id);
      if (!existingListing || existingListing.sellerId !== user?.id) {
        return res.status(403).json({ message: "Not authorized to edit this listing" });
      }

      const parsedUpdates = insertMarketplaceListingSchema
        .partial()
        .safeParse(pickMarketplaceWritableFields(req.body));

      if (!parsedUpdates.success) {
        return res.status(400).json({
          message: "Invalid marketplace listing update payload",
          issues: parsedUpdates.error.issues,
        });
      }

      const updates = normalizeMarketplaceWritableFields(parsedUpdates.data as any);
      if (Object.keys(updates).length === 0) {
        return res.status(400).json({ message: "No permitted updates provided" });
      }

      const nextMarketplaceKey = buildMarketplaceIngressKey({
        sellerId: String(user?.id || ""),
        categoryId: String(updates.categoryId || existingListing.categoryId || ""),
        title: String(updates.title || existingListing.title || ""),
        county: String(updates.county || existingListing.county || ""),
        state: String(updates.state || existingListing.state || ""),
        price: String(updates.price || existingListing.price || ""),
      });

      const siblingListings = await storage.getUserListings(String(user?.id || ""));
      const duplicateListing = siblingListings.find((listing: any) => {
        if (String(listing?.id || "") === String(id)) return false;
        const status = String(listing?.status || "").toLowerCase();
        if (!["draft", "pending_approval", "active"].includes(status)) return false;

        const existingKey = buildMarketplaceIngressKey({
          sellerId: String(listing?.sellerId || ""),
          categoryId: String(listing?.categoryId || ""),
          title: String(listing?.title || ""),
          county: String(listing?.county || ""),
          state: String(listing?.state || ""),
          price: String(listing?.price || ""),
        });

        return existingKey === nextMarketplaceKey;
      });

      if (duplicateListing) {
        return res.status(409).json({
          message: "A matching marketplace listing is already pending or active.",
          listingId: duplicateListing.id,
          reasonCode: "DUPLICATE_MARKETPLACE_LISTING",
        });
      }

      // Prohibited items + cottage food validation on update
      const updateCategoryId = String(updates.categoryId || existingListing.categoryId || "");
      const updateCategoryName = await getMarketplaceCategoryNameById(updateCategoryId);
      const updateExchangeSlug =
        getExchangeCategorySlugFromMarketplaceCategoryName(updateCategoryName);
      if (updateExchangeSlug && updateExchangeSlug !== "metals") {
        let sellerStateForUpdate: string | null = null;
        try {
          const [sellerProfile] = await storage.getUsersByIds([String(user?.id || "")]);
          sellerStateForUpdate =
            String((sellerProfile as any)?.state || "")
              .toUpperCase()
              .trim() || null;
        } catch {
          /* non-fatal */
        }
        const updateValidation = validateExchangeCategoryListing({
          category: updateExchangeSlug,
          imageCount: Array.isArray((updates as any)?.images)
            ? (updates as any).images.length
            : Array.isArray((existingListing as any)?.images)
              ? (existingListing as any).images.length
              : 0,
          specs: ((updates as any)?.specifications ||
            (existingListing as any)?.specifications ||
            null) as Record<string, unknown> | null,
          title: String((updates as any)?.title || (existingListing as any)?.title || ""),
          description: String(
            (updates as any)?.description || (existingListing as any)?.description || ""
          ),
          sellerState: sellerStateForUpdate,
        });
        if (updateValidation) {
          return res.status(400).json(updateValidation);
        }
      }

      const listing = await storage.updateMarketplaceListing(id, updates);
      res.json(listing);
    } catch (error: any) {
      console.error("Error updating marketplace listing:", error);
      res.status(400).json({ message: "Failed to update listing" });
    }
  });

